package com.matejpcs.netflared;
import com.google.gson.*;import java.io.*;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.nio.file.attribute.PosixFilePermission;import java.util.*;import java.util.concurrent.TimeUnit;import java.util.concurrent.atomic.AtomicBoolean;
public final class CloudflaredManager{private static final String API="https://api.github.com/repos/cloudflare/cloudflared/releases/latest";private final Path bin,token;private final HttpClient http=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NORMAL).build();private Process process;private final AtomicBoolean stopping=new AtomicBoolean();public CloudflaredManager(Path d){bin=d.resolve("bin").resolve(Platform.executableName());token=d.resolve("tunnel.token");}public synchronized boolean isRunning(){return process!=null&&process.isAlive();}public synchronized Path ensureBinary()throws IOException,InterruptedException{if(Files.isRegularFile(bin))return bin;if(!Platform.supported())throw new IOException("Unsupported platform: "+Platform.id());Files.createDirectories(bin.getParent());HttpResponse<String>r=http.send(HttpRequest.newBuilder(URI.create(API)).header("User-Agent","Netflared-Server").GET().build(),HttpResponse.BodyHandlers.ofString());JsonArray a=JsonParser.parseString(r.body()).getAsJsonObject().getAsJsonArray("assets");String u=null;for(JsonElement e:a){JsonObject x=e.getAsJsonObject();if(asset().equals(x.get("name").getAsString()))u=x.get("browser_download_url").getAsString();}if(u==null)throw new IOException("No cloudflared binary for "+Platform.id());HttpResponse<InputStream>d=http.send(HttpRequest.newBuilder(URI.create(u)).header("User-Agent","Netflared-Server").GET().build(),HttpResponse.BodyHandlers.ofInputStream());Path t=bin.resolveSibling("download");try(InputStream in=d.body()){Files.copy(in,t,StandardCopyOption.REPLACE_EXISTING);}Files.move(t,bin,StandardCopyOption.REPLACE_EXISTING);return bin;}public synchronized void start(String t)throws IOException{if(isRunning())return;stopping.set(false);Files.createDirectories(token.getParent());Files.writeString(token,t);process=new ProcessBuilder(bin.toString(),"tunnel","run","--token-file",token.toString()).redirectErrorStream(true).start();Process p=process;Thread m=new Thread(()->monitor(p,t));m.setDaemon(true);m.start();}private void monitor(Process p,String t){try{p.getInputStream().transferTo(System.out);p.waitFor();if(!stopping.get()){Thread.sleep(5000);synchronized(this){if(!stopping.get()&&process==p){process=null;start(t);}}}}catch(Exception ignored){}}public synchronized void stop(){stopping.set(true);if(process!=null){process.destroy();try{if(!process.waitFor(5,TimeUnit.SECONDS))process.destroyForcibly();}catch(InterruptedException e){Thread.currentThread().interrupt();}process=null;}}public Path binary(){return bin;}public void clearTokenFile()throws IOException{Files.deleteIfExists(token);}private static String asset(){return switch(Platform.id()){case"linux-amd64"->"cloudflared-linux-amd64";case"linux-arm64"->"cloudflared-linux-arm64";case"linux-arm"->"cloudflared-linux-arm";case"linux-386"->"cloudflared-linux-386";case"windows-amd64"->"cloudflared-windows-amd64.exe";case"windows-arm64"->"cloudflared-windows-arm64.exe";case"windows-386"->"cloudflared-windows-386.exe";default->throw new IllegalStateException("Unsupported platform");};}}
